click.script:
if (!window.confirm('Close this thread?')) return;
call('connect.api.close_thread', { thread: selectedThread.value }).then(() => {
	myThreads.reload();
	messages.reload();
	toast({ title: 'Thread closed', icon: 'check', iconClasses: 'text-green-600' });
}).catch((e) => {
	toast({ title: 'Could not close thread', text: e.messages ? e.messages[0] : e.message, icon: 'x-circle', iconClasses: 'text-red-600' });
});

keydown.script:
if (eventArgs[0] && eventArgs[0].key === 'Enter') { eventArgs[0].preventDefault(); if (!draftMessage.value || !selectedThread.value) return;
call('frappe.client.insert', {
	doc: {
		doctype: 'Connect Message',
		thread: selectedThread.value,
		sender: myContext.data.user,
		message_type: 'Text',
		content: draftMessage.value,
	}
}).then(() => {
	draftMessage.value = '';
	messages.reload();
}).catch((e) => {
	toast({ title: 'Could not send message', text: e.messages ? e.messages[0] : e.message, icon: 'x-circle', iconClasses: 'text-red-600' });
}); }

